ChangerEtatAbsence(ALigne,AColonne){if(this.EstUneCelluleActive(AColonne)&&!this.DeterminerSiEstUneCelluleAvecDispense(ALigne,AColonne)&&!this.DeterminerSiEstUneCelluleAvecExclusionTemporaire(ALigne,AColonne)){const LEleve=this.ListeElements.GetElement(ALigne);if(!_avecSaisieAutoriseSelonEleveEtTypeAbsence(LEleve,this.TypeAbsence,this.cours)){return;}
const N=LEleve.ListeAbsences.GetNbrElements();for(let J=0;J<N;J++){const LAbsence=LEleve.ListeAbsences.GetElement(J);if(LAbsence.Etat!==EGenreEtat.Suppression){if((LAbsence.GetGenre()===EGenreRessource.Absence)&&(AColonne===LAbsence.PlaceFin)){if(this.AvecAutorisationSaisieAbsOuverte){if(this.autoriseDeChangerLAbsence(LAbsence,LEleve)){const LMessage=(LAbsence.EstOuverte?GTraductions.getValeur('AbsenceVS.msgClotureAbsence'):GChaine.Format(GTraductions.getValeur('AbsenceVS.msgOuvrirAbsence'),new Array(GDate.FormatDate(this.Date,'%JJ/%MM'),GDate.FormatDate(GDate.PlaceAnnuelleEnDate(LAbsence.PlaceDebut),'%hh%sh%mm ?'))));const lThis=this;GApplication.getMessage().afficher({type:EGenreBoiteMessage.Confirmation,message:LMessage,callback:function(aGenreAction){lThis.SurValidationChangerEtatAbsence(aGenreAction,ALigne,AColonne);}});}
if((!this.AvecOptionSaisieAutresProfs)&&(GDate.PlaceAnnuelleEnDate(this.PlaceSaisieFin,true)<new Date())){GApplication.getMessage().afficher({type:EGenreBoiteMessage.Information,message:GTraductions.getValeur('AbsenceVS.msgImpossibleOuvrirAbsence')});}}}}}
this.CreerTableauCellules();this.SetDonneesLigne(ALigne);}}
autoriseDeChangerLAbsence(aAbsence,aEleve){const lPlaceAnnuelleCourante=GDate.DateEnPlaceAnnuelle(new Date());const lAbsencePrecedent=this.absencePrecedentContigu(aAbsence,aEleve);const lPlaceDebut=lAbsencePrecedent?lAbsencePrecedent.PlaceDebut:aAbsence.PlaceDebut;const JourMeme=(GDate.estJourSemaineEgal(this.Date,new Date()));const HeureActuellePassee=(lPlaceDebut<=lPlaceAnnuelleCourante);const SurPremierCellule=(lPlaceAnnuelleCourante>this.PlaceSaisieDebut)||((this.AvecOptionSaisieAutresProfs));const AvantFinPlageSaisie=(this.AvecOptionSaisieAutresProfs)||(this.PlaceSaisieFin>=lPlaceAnnuelleCourante);const ExisteAbsenceUlterieur=aAbsence.PlaceFin<aEleve.DernierePlace;return JourMeme&&SurPremierCellule&&HeureActuellePassee&&AvantFinPlageSaisie&&!ExisteAbsenceUlterieur;}
absencePrecedentContigu(aAbsence,aEleve){const N=aEleve.ListeAbsences.GetNbrElements();for(let J=0;J<N;J++){const lAbsence=aEleve.ListeAbsences.GetElement(J);if((lAbsence.GetGenre()===aAbsence.GetGenre())&&(lAbsence.GetNumero()!==aAbsence.GetNumero())&&lAbsence.Existe()){if(lAbsence.PlaceFin===aAbsence.PlaceDebut-1){return lAbsence;}}}
return null;}
SurValidationChangerEtatAbsence(AAccepte,ALigne,AColonne){if(AAccepte===EGenreAction.Valider){if(this.EstUneCelluleActive(AColonne)){const LEleve=this.ListeElements.GetElement(ALigne);LEleve.ExisteAbsenceOuverte=false;const N=LEleve.ListeAbsences.GetNbrElements(),lPlaceCourante=GDate.DateEnPlaceAnnuelle(new Date());for(let J=0;J<N;J++){let LAbsence=LEleve.ListeAbsences.GetElement(J);if(LAbsence.Etat!==EGenreEtat.Suppression){if((LAbsence.GetGenre()===EGenreRessource.Absence)&&(AColonne===LAbsence.PlaceFin)){if(this.AvecAutorisationSaisieAbsOuverte){if((GDate.estJourSemaineEgal(this.Date,new Date()))&&((this.AvecOptionSaisieAutresProfs)||(GDate.PlaceAnnuelleEnDate(this.PlaceSaisieFin,true)>new Date()))){if(LAbsence.PlaceDebut>lPlaceCourante){LAbsence.SetEtat(EGenreEtat.Suppression);LAbsence=this.absencePrecedentContigu(LAbsence,LEleve);}
LAbsence.PlaceFin=lPlaceCourante;LAbsence.EstOuverte=(!LAbsence.EstOuverte);LAbsence.SetEtat(EGenreEtat.Modification);}}}}}
this.callback.appel(EGenreEvenementSaisieAbsence.CalculInfoEleve,{eleve:LEleve});this.CreerTableauCellules();this.SetDonneesLigne(ALigne);this.SetEtatSaisie(true);}}}
SurPreResize(){if(this.EnAffichage){GHtml.setHtml(this.Nom,'&nbsp;');if(this.FenetreInfirmerie&&this.FenetreInfirmerie.EstAffiche()){this.FenetreInfirmerie.SurValidation(0);}}}
SurPostResize(){if(this.EnAffichage){this.RechargerAffichage();}}
EnDeplacement(AGenreBorne){this.Deplacement=true;this.GenreBorneDeplacee=AGenreBorne;GNavigateur.DebDeplacement(this,this.IdBorne+AGenreBorne);}
