clicValorisation(event){const lNumEleve=$(this).parent('div').parent('td').attr('id').match(/[a-z0-9]+(?=_lib$)/i)[0];event.data.aObjet.callback.appel(EGenreEvenementSaisieAbsence.ValorisationsEleve,{numeroEleve:lNumEleve});}
clicDroitEleve(event){const lNumEleve=$(this).parent('div').parent('td').attr('id').match(/[a-z0-9]+(?=_lib$)/i)[0];$('#'+event.data.aObjet.Nom.escapeJQ()+' table.tableAbsenceEleve td[id$="_'+lNumEleve+'_lib"]').click();event.data.aObjet.callback.appel(EGenreEvenementSaisieAbsence.ContextMenuEleve,{numeroEleve:lNumEleve});}
retourChangementDevoir(aNumEleve){const lEleve=this.listeEleves.GetElementParNumero(aNumEleve);const lJqCelluleEleve=$('#'+this.Nom.escapeJQ()+' table.tableAbsenceEleve td[id$="_'+aNumEleve+'_lib"]');let lClassDevARendre='';if(lEleve.devoirARendre.Numero!==null){if(lEleve.devoirARendre.programmation.Genre===1){lClassDevARendre='icon_filigrane_idevoir_rendu';} else{lClassDevARendre='icon_filigrane_idevoir';}}
lJqCelluleEleve.children('div').children('div.tableAbsenceEleveDevARendre').removeClass('icon_filigrane_idevoir_rendu icon_filigrane_idevoir').addClass(lClassDevARendre);}
retourAbsence(aNumEleve,aGenreAbs,aNumObs){const lEleve=this.listeEleves.GetElementParNumero(aNumEleve);let lColonne=lEleve.listeColonnes.GetElementParNumeroEtGenre(aNumObs,aGenreAbs);const lJqCellAbs=$('#'+this.Nom.escapeJQ()+' table.tableAbsenceCorps div[id*="_'+aNumEleve+'_'+aGenreAbs+'_abs'+(aNumObs?'_'+aNumObs:'')+'"]');if(!lColonne){lEleve.listeColonnes.AddElement(new ObjetElement("",aNumObs,aGenreAbs));lColonne=lEleve.listeColonnes.GetElementParNumeroEtGenre(aNumObs,aGenreAbs);lColonne.nombre=0;if(aGenreAbs===EGenreRessource.Observation){lColonne.genreObservation=lJqCellAbs.attr('id').match(/_([0-9a-z]+)$/)[1];}}
lJqCellAbs.html(this.moteur.getAffichageGenre(aNumEleve,aGenreAbs,aNumObs,(lColonne.Genre===EGenreRessource.Observation?lColonne.genreObservation:null)));const lChecked=this.moteur.aUneAbsence(aNumEleve,aGenreAbs,aNumObs)>=0?'true':'false';lJqCellAbs.attr('aria-checked',lChecked);this.setCellulesInactives(aNumEleve);if(aGenreAbs===EGenreRessource.Retard&&this.moteur.avecSaisieMotif(aGenreAbs)&&this.moteur.aUneAbsence(aNumEleve,aGenreAbs,aNumObs)>=0){this.ouvrirZoneTexte(aNumEleve,aGenreAbs,aNumObs);}}
ouvrirZoneTexte(aNumEleve,aGenreAbs,aNumObs,aTypeObs,aGenreEtat){const lJqContainer=$('#'+this.Nom.escapeJQ()+' table.tableAbsenceCorps div[id*="_'+aNumEleve+'_'+aGenreAbs+'_abs'+(aNumObs?'_'+aNumObs:'')+'"]').parent();if(lJqContainer.children('input, textarea').length>0){return false;}
let lJqZoneTexte="";const lAbsence=this.callback.appel(EGenreEvenementSaisieAbsence.RecupererAbsence,{genreAbsence:aGenreAbs,genreObservation:aNumObs,place:this.placeSaisieDebut});if(aGenreAbs===EGenreRessource.Retard){lJqZoneTexte=$('<input type="text" />');lJqZoneTexte.val(lAbsence.Duree).css({border:"0",padding:"0",margin:"0",width:lJqContainer.width(),height:lJqContainer.height()});} else if(aGenreAbs===EGenreRessource.Observation||aGenreAbs===EGenreRessource.Dispense){this.callback.appel(EGenreEvenementSaisieAbsence.OuvrirEditionObservation,{absence:lAbsence,genreObservation:aNumObs,genreEtat:aGenreEtat,typeObs:aTypeObs});return false;} else{return false;}
lJqContainer.children("div").hide();lJqContainer.append(lJqZoneTexte);lJqZoneTexte.focus().each(function(){if(typeof this.setSelectionRange!=="undefined"){this.setSelectionRange(0,this.value.length);} else if(typeof this.createTextRange!=="undefined"){const range=this.createTextRange();range.collapse(true);range.moveEnd('character',this.value.length);range.moveStart('character',0);range.select();}});lJqZoneTexte.keyup({aObjet:this},this.keydownZoneTexte).blur({aObjet:this},this.blurZoneTexte).click(function(){return false;}).on('contextmenu',function(){return false;});return false;}
ouvrirFenetreAbsencesParPas(aNumEleve,aGenreAbs){const lAbsence=this.moteur.aUneAbsence(aNumEleve,aGenreAbs);if(lAbsence> -1){this.callback.appel(EGenreEvenementSaisieAbsence.OuvrirAbsenceParPas,{absence:this.listeEleves.GetElementParNumero(aNumEleve).ListeAbsences.GetElement(lAbsence)});}
return false;}
keydownZoneTexte(){const lGenreCol=parseInt($(this).parent().children('div:first-child').attr('id').match(/_([a-z0-9]+)_([a-z0-9]+)(?=_abs)/i)[2]);if(lGenreCol===EGenreRessource.Retard){$(this).delay(1).queue(function(){const lDuree=parseInt($(this).val().replace(/[^0-9]/g,'').substr(0,3));$(this).val(lDuree>0?lDuree:'').dequeue();});}
if(GNavigateur.IsToucheRetourChariot()||GNavigateur.IsToucheEchap()){$(this).blur();}}
blurZoneTexte(event){const lNumEleve=$(this).parent().children('div:first-child').attr('id').match(/_([a-z0-9]+)_([a-z0-9]+)(?=_abs)/i)[1];const lGenreCol=parseInt($(this).parent().children('div:first-child').attr('id').match(/_([a-z0-9]+)_([a-z0-9]+)(?=_abs)/i)[2]);let lNumObs=null;if(lGenreCol===EGenreRessource.Observation){lNumObs=$(this).parent().children('div:first-child').attr('id').match(/abs_([a-z0-9]+)_([a-z0-9]+)$/i)[1];}
if($(this).val().trim()===''){event.data.aObjet.callback.appel(EGenreEvenementSaisieAbsence.ActionSurAbsence,{typeSaisie:EGenreEtat.Suppression,typeAbsence:lGenreCol,typeObservation:lNumObs,numeroEleve:event.data.aObjet.numeroEleveSelectionne,placeDebut:event.data.aObjet.placeSaisieDebut,placeFin:event.data.aObjet.placeSaisieFin});} else{const lAbsence=event.data.aObjet.callback.appel(EGenreEvenementSaisieAbsence.RecupererAbsence,{genreAbsence:lGenreCol,genreObservation:lNumObs,place:event.data.aObjet.placeSaisieDebut});if(lGenreCol===EGenreRessource.Retard){const lDuree=parseInt($(this).val().replace(/[^0-9]/g,'').substr(0,3));if((lAbsence.Duree!==lDuree)&&(lDuree<=240)){lAbsence.Duree=lDuree;$(this).val(lDuree>0?lDuree:'');lAbsence.SetEtat(EGenreEtat.Modification);event.data.aObjet.SetEtatSaisie(true);}} else if(lGenreCol===EGenreRessource.Observation&&lAbsence.commentaire!==$(this).val()){lAbsence.commentaire=$(this).val().trim();lAbsence.SetEtat(EGenreEtat.Modification);event.data.aObjet.SetEtatSaisie(true);}}
$(this).parent().children('div').show();event.data.aObjet.retourAbsence(lNumEleve,lGenreCol,lNumObs);$(this).remove();if(event.data.aObjet._gestionFocus_apresFenetreCelluleId){GHtml.setFocus(event.data.aObjet._gestionFocus_apresFenetreCelluleId,true,true);}
return false;}
