function _evenementSurComboTaillePolice(aSurTaillePolice,aGenreEvenement,aElement){switch(aGenreEvenement){case EGenreEvenementObjetSaisie.selection:if(!aElement){return;}
if(aSurTaillePolice){this._optionsPDF.taillePolice=aElement.valeur;if(this._optionsPDF.taillePolice<this._optionsPDF.taillePoliceMin){this._optionsPDF.taillePoliceMin=this._optionsPDF.taillePolice;}} else{this._optionsPDF.taillePoliceMin=aElement.valeur;if(this._optionsPDF.taillePoliceMin>this._optionsPDF.taillePolice){this._optionsPDF.taillePolice=this._optionsPDF.taillePoliceMin;}}
break;}}
