if(this._parametres.PARAMETRE_FENETRE.avecChoixCouleurCours){aHtml.push(this.composeGroupe(GTraductions.getValeur('GenerationPDF.EDT.CouleurCours'),'<ie-radio ie-model="rbCouleur('+EGenreCouleurTexte_EDT.aucune+')" class="Texte10" style="margin:2px;">'+GTraductions.getValeur('GenerationPDF.EDT.Aucune')+'</ie-radio>'+'<br />'+'<ie-radio ie-model="rbCouleur('+EGenreCouleurTexte_EDT.fond+')" class="Texte10" style="margin:2px;">'+GTraductions.getValeur('GenerationPDF.EDT.FondCouleur')+'</ie-radio>'+'<br />'+'<ie-radio ie-model="rbCouleur('+EGenreCouleurTexte_EDT.texte+')" class="Texte10" style="margin:2px;">'+GTraductions.getValeur('GenerationPDF.EDT.TexteCouleur')+'</ie-radio>'));}
